.title-rules b { display: block; color: var(--gold); font-size: 14px; margin-bottom: 3px; }
.title-rules span { font-size: 13px; line-height: 1.35; color: var(--ink-dim); }
.difficulty { display: flex; gap: 10px; }
.diff-btn { background: #1d3a2a; color: var(--ink-dim); border: 1px solid #3a5a44; border-radius: 8px;
  padding: 8px 22px; font-size: 15px; cursor: pointer; font-family: inherit; }
.diff-btn.selected { background: var(--gold); color: #241a05; border-color: var(--gold); font-weight: 700; }
.big-btn { background: linear-gradient(#ff8a3d, #e85d1f); color: #fff; border: none; border-radius: 12px;
  padding: 14px 44px; font-size: 22px; font-weight: 800; letter-spacing: 1px; cursor: pointer;
  box-shadow: 0 6px 0 #8f3410, 0 10px 24px rgba(0,0,0,.5); font-family: inherit; }
.big-btn:hover { filter: brightness(1.1); }
.big-btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #8f3410; }
.controls-hint { font-size: 13px; color: #8fa596; }
.best-line { font-size: 14px; color: var(--gold); min-height: 18px; }

/* ---------- Table ---------- */
#table-screen { background: linear-gradient(#1d3a2a, #14261c 45%, #1d3a2a);
  border: 10px solid #4a3220; border-radius: 18px; outline: 2px solid #6b4a26; }
#opponent-bar, #player-bar { display: flex; align-items: center; gap: 14px; padding: 8px 16px; }
.portrait { width: 52px; height: 52px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-size: 30px; background: #0d1a12; border: 3px solid var(--gold-dim); flex: none; }
.portrait.foe { border-color: #c0392b; }
.hero-info { width: 340px; }
.hero-name { font-size: 17px; font-weight: 800; margin-bottom: 4px; }
.hero-sub { font-size: 12px; color: var(--ink-dim); font-weight: 400; }
.hp-track { position: relative; height: 22px; background: #0d1a12; border: 1px solid #3a5a44; border-radius: 11px; overflow: hidden; }
.hp-fill { height: 100%; transition: width .4s ease; }
.foe-hp { background: linear-gradient(#e74c3c, #a93226); }
.you-hp { background: linear-gradient(#58b368, #2e7d3a); }
.hp-text { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 13px; font-weight: 800; text-shadow: 0 1px 2px #000; }
.armor-line { font-size: 12px; color: #9fc3ff; min-height: 15px; margin-top: 2px; }
.mana-pips { display: flex; gap: 4px; flex-wrap: wrap; width: 150px; }
.mana-pip { width: 16px; height: 16px; border-radius: 50%; background: #123a5e; border: 1px solid #2f6ea8; }
.mana-pip.full { background: radial-gradient(circle at 35% 35%, #9fd8ff, #2f8fd8); box-shadow: 0 0 6px #2f8fd8; }
.deck-count { font-size: 13px; color: var(--ink-dim); background: #0d1a12; border: 1px solid #3a5a44;
  border-radius: 8px; padding: 6px 10px; white-space: nowrap; }
.end-btn { margin-left: auto; background: linear-gradient(#f2b544, #c98f2b); color: #241a05; border: none;
  border-radius: 10px; padding: 12px 26px; font-size: 17px; font-weight: 800; cursor: pointer; font-family: inherit;
  box-shadow: 0 4px 0 #7a5a10; }
.end-btn:hover:not(:disabled) { filter: brightness(1.1); }
.end-btn:disabled { opacity: .45; cursor: default; }

.hand { display: flex; gap: 6px; justify-content: center; min-height: 78px; align-items: center; padding: 2px 10px; }
.foe-hand .card-back { width: 44px; height: 64px; }
.board { display: flex; gap: 10px; justify-content: center; min-height: 108px; align-items: center; padding: 2px 10px; }
.board .empty-note { color: #6f8a76; font-size: 13px; font-style: italic; }
#midline { display: flex; align-items: center; gap: 12px; padding: 0 16px; min-height: 34px; }
#turn-banner { font-size: 15px; font-weight: 800; color: var(--gold); white-space: nowrap; min-width: 170px; }
#turn-banner.foe-turn { color: #ff8a6a; }
#combat-log { flex: 1; font-size: 13px; color: var(--ink-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#target-hint { position: absolute; left: 50%; top: 330px; transform: translateX(-50%); background: #f2b544; color: #241a05;
  font-weight: 700; font-size: 14px; padding: 8px 16px; border-radius: 8px; z-index: 30; box-shadow: 0 4px 16px rgba(0,0,0,.6); }

/* ---------- Cards ---------- */
.card { width: var(--card-w); height: var(--card-h); border-radius: 12px; position: relative; flex: none;
  background: linear-gradient(#f7ecd2, #e8d5a8); color: #2b1d0e; border: 3px solid #7a5a26;
  box-shadow: 0 4px 10px rgba(0,0,0,.55); cursor: pointer; transition: transform .12s ease, box-shadow .12s ease;
  user-select: none; font-family: inherit; text-align: left; }
.card.creature { border-color: #8a5a1d; }
.card.spell-damage { border-color: #a93226; background: linear-gradient(#f9e2d8, #ecc3ae); }
.card.spell-heal { border-color: #2e7d3a; background: linear-gradient(#e2f2df, #c2e0ba); }
.card.spell-shield { border-color: #2f6ea8; background: linear-gradient(#ddebf9, #bcd8ef); }
.player-hand .card:hover:not(.unplayable) { transform: translateY(-14px) scale(1.05); box-shadow: 0 10px 18px rgba(0,0,0,.65); }
.card.unplayable { filter: grayscale(.55) brightness(.75); cursor: not-allowed; }
.card.selected { outline: 4px solid var(--gold); transform: translateY(-14px); box-shadow: 0 0 22px rgba(242,181,68,.8); }
.card .cost { position: absolute; top: -8px; left: -8px; width: 34px; height: 34px; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #9fd8ff, #2470b8); color: #fff; font-weight: 900; font-size: 18px;
  display: flex; align-items: center; justify-content: center; border: 2px solid #123a5e; text-shadow: 0 1px 2px #000; }
.card .name { font-size: 14px; font-weight: 800; text-align: center; padding: 8px 6px 2px; min-height: 34px; line-height: 1.1; }
.card .art { height: 68px; margin: 2px 10px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
  font-size: 46px; background: radial-gradient(circle at 50% 40%, rgba(255,255,255,.55), rgba(0,0,0,.12)); border: 1px solid rgba(0,0,0,.15); }
.card .text { font-size: 12px; line-height: 1.3; text-align: center; padding: 2px 8px; min-height: 34px; color: #4a3416; }
.card .stats { position: absolute; bottom: 6px; left: 0; right: 0; display: flex; justify-content: space-between; padding: 0 10px; }
.card .atk, .card .hp { width: 30px; height: 30px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-weight: 900; font-size: 16px; color: #fff; text-shadow: 0 1px 2px #000; }
.card .atk { background: radial-gradient(circle at 35% 35%, #ff9a5c, #d84a12); border: 2px solid #8f2a00; }
.card .hp { background: radial-gradient(circle at 35% 35%, #8fd694, #2e7d3a); border: 2px solid #14511d; }
.card .type-tag { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%); font-size: 10px;
  letter-spacing: 2px; text-transform: uppercase; color: #7a5a26; font-weight: 700; }
.card.on-board { width: 104px; height: 138px; cursor: default; }
.card.on-board .cost { width: 26px; height: 26px; font-size: 14px; top: -6px; left: -6px; }
.card.on-board .name { font-size: 11px; padding: 6px 2px 2px 22px; text-align: left; }
.card.on-board .art { height: 52px; font-size: 36px; }
.card.on-board .name { font-size: 12px; }
.card.on-board .text { display: none; }
.card.on-board:hover { transform: none; }
.card.targetable { outline: 3px solid #ff5a3c; cursor: crosshair; animation: pulse 1s infinite; }
@keyframes pulse { 50% { outline-color: #ffd23c; } }
.card-back { width: 44px; height: 64px; border-radius: 6px; background: repeating-linear-gradient(45deg, #7a2a1d 0 8px, #5a1d14 8px 16px);
  border: 2px solid #d8a03c; }
.card.fresh { animation: deal .25s ease; }
@keyframes deal { from { transform: translateY(24px); opacity: 0; } }

/* ---------- End screen ---------- */
#end-screen { align-items: center; justify-content: center; gap: 16px; text-align: center; }
#end-title { font-size: 76px; letter-spacing: 6px; font-weight: 900; }
#end-title.win { color: var(--gold); text-shadow: 0 0 30px rgba(242,181,68,.8); }
#end-title.lose { color: #e74c3c; text-shadow: 0 0 30px rgba(231,76,60,.7); }
#end-sub { font-size: 19px; color: var(--ink-dim); max-width: 640px; line-height: 1.5; }
#end-stats { display: flex; gap: 14px; }
#end-stats div { background: rgba(0,0,0,.35); border: 1px solid #3a5a44; border-radius: 10px; padding: 12px 20px; }
#end-stats b { display: block; font-size: 26px; color: var(--gold); }
#end-stats span { font-size: 12px; color: var(--ink-dim); }

#float-layer { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.float-num { position: absolute; font-size: 26px; font-weight: 900; text-shadow: 0 2px 4px #000; animation: floatUp 1.1s ease forwards; }
.float-num.dmg { color: #ff6a4d; }
.float-num.heal { color: #7ddb8a; }
.float-num.shield { color: #9fc3ff; }
@keyframes floatUp { to { transform: translateY(-56px); opacity: 0; } }
#mute-btn { position: absolute; right: 12px; bottom: 12px; z-index: 40; background: rgba(0,0,0,.4); border: 1px solid #3a5a44;
  color: var(--ink); border-radius: 8px; width: 36px; height: 36px; font-size: 18px; cursor: pointer; }
.shot-mode #mute-btn { display: none; }
